/**
 * ConfidenceIndicator — colored dot + optional detail popover.
 *
 * Renders a small (12×12px) filled circle whose color reflects the
 * current GPS/heading confidence level.  Tapping the dot toggles a
 * small inline label showing the level name.
 */

import { useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import { ConfidenceLevel } from '../../routing/guidanceState';

export { ConfidenceLevel } from '../../routing/guidanceState';

// ─── Color map ────────────────────────────────────────────────────────────────

const DOT_COLOR: Record<ConfidenceLevel, string> = {
  high: '#22c55e',   // green
  medium: '#eab308', // yellow
  low: '#f97316',    // orange
  none: '#ef4444',   // red
};

const LABEL_COLOR: Record<ConfidenceLevel, string> = {
  high: '#4ade80',
  medium: '#facc15',
  low: '#fb923c',
  none: '#f87171',
};

const LABEL_TEXT: Record<ConfidenceLevel, string> = {
  high: 'GPS OK',
  medium: 'Heading?',
  low: 'Weak GPS',
  none: 'No GPS',
};

const ICON_MAP: Record<ConfidenceLevel, string> = {
  high: '',
  medium: '',
  low: '',
  none: '⚠',
};

interface Props {
  confidence: ConfidenceLevel;
}

export function ConfidenceIndicator({ confidence }: Props) {
  const [showLabel, setShowLabel] = useState(false);

  const dotColor = DOT_COLOR[confidence];
  const labelColor = LABEL_COLOR[confidence];
  const labelText = LABEL_TEXT[confidence];
  const icon = ICON_MAP[confidence];

  return (
    <Pressable
      style={styles.container}
      onPress={() => setShowLabel(s => !s)}
      accessibilityRole="button"
      accessibilityLabel={`GPS confidence: ${confidence}`}
      testID="confidence-indicator"
    >
      <View style={[styles.dot, { backgroundColor: dotColor }]}>
        {icon ? <Text style={styles.icon}>{icon}</Text> : null}
      </View>
      {showLabel && (
        <View style={[styles.labelBadge, { backgroundColor: dotColor + '33', borderColor: dotColor }]}>
          <Text style={[styles.labelText, { color: labelColor }]}>
            {labelText}
          </Text>
        </View>
      )}
    </Pressable>
  );
}

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  dot: {
    width: 12,
    height: 12,
    borderRadius: 9999,
    alignItems: 'center',
    justifyContent: 'center',
  },
  icon: {
    fontSize: 7,
    color: '#fff',
    lineHeight: 9,
  },
  labelBadge: {
    position: 'absolute',
    top: 16,
    left: '50%',
    transform: [{ translateX: -30 }],
    width: 60,
    borderWidth: 1,
    borderRadius: 6,
    paddingHorizontal: 6,
    paddingVertical: 3,
    alignItems: 'center',
  },
  labelText: {
    fontSize: 10,
    fontWeight: '600',
  },
});

/**
 * DestinationPicker — building/floor/node accordion with fuzzy text search.
 * Pressing a node calls onNodeSelect. "Set Start" / "Set Destination" toggle
 * in header reflects the activeField from RouteSelection.
 */

import { useEffect, useState } from 'react';
import {
  FlatList,
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';

import { useLocationSearch } from '../../hooks/useLocationSearch';
import { NormalizedNavGraph } from '../../domain/navGraph';
import { NavNode } from '../../../src/shared/types';
import { RouteSelection } from '../../hooks/useRouteSelection';

const DEBOUNCE_MS = 300;

interface Props {
  graph: NormalizedNavGraph;
  selection: RouteSelection;
  onNodeSelect: (node: NavNode) => void;
}

const TYPE_BADGE: Record<string, string> = {
  room: '📍',
  entrance: '🚪',
  elevator: '🛗',
  restroom: '🚻',
  landmark: '⭐',
  stairs: '⬆️',
  ramp: '♿',
  junction: '⬡',
  hallway: '─',
};

const ACCESSIBLE_ICON = '♿';

export function DestinationPicker({ graph, selection, onNodeSelect }: Props) {
  const [query, setQuery] = useState('');
  const [debouncedQuery, setDebouncedQuery] = useState('');

  // Debounce search input
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedQuery(query);
    }, DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [query]);

  const { buildings, totalMatches } = useLocationSearch(graph, debouncedQuery);

  const activeLabel = selection.activeField === 'start' ? 'Set Start' : 'Set Destination';
  const otherLabel = selection.activeField === 'start' ? 'Set Destination' : 'Set Start';

  return (
    <View style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <Text style={styles.headerLabel}>{activeLabel}</Text>
        <Text style={styles.resultCount}>
          {totalMatches} {totalMatches === 1 ? 'result' : 'results'}
        </Text>
      </View>

      {/* Search input */}
      <TextInput
        style={styles.searchInput}
        placeholder="Search location..."
        placeholderTextColor="#64748b"
        value={query}
        onChangeText={setQuery}
        autoCapitalize="none"
        autoCorrect={false}
      />

      {/* Active field indicator */}
      <View style={styles.fieldToggle}>
        <Text style={styles.fieldText}>Picking: </Text>
        <Pressable
          style={[styles.fieldChip, selection.activeField === 'start' && styles.fieldChipActive]}
          onPress={() => selection.setActiveField('start')}
        >
          <Text style={[styles.fieldChipText, selection.activeField === 'start' && styles.fieldChipTextActive]}>
            Start {selection.start ? `(${selection.start.label})` : ''}
          </Text>
        </Pressable>
        <Pressable
          style={[styles.fieldChip, selection.activeField === 'destination' && styles.fieldChipActive]}
          onPress={() => selection.setActiveField('destination')}
        >
          <Text style={[styles.fieldChipText, selection.activeField === 'destination' && styles.fieldChipTextActive]}>
            Dest {selection.destination ? `(${selection.destination.label})` : ''}
          </Text>
        </Pressable>
        {(selection.start || selection.destination) && (
          <Pressable style={styles.swapButton} onPress={selection.swap}>
            <Text style={styles.swapButtonText}>⇄ Swap</Text>
          </Pressable>
        )}
      </View>

      {/* Results */}
      <FlatList
        data={buildings}
        keyExtractor={item => String(item.buildingId)}
        style={styles.list}
        renderItem={({ item: building }) => (
          <BuildingAccordion
            building={building}
            onNodeSelect={onNodeSelect}
          />
        )}
        ListEmptyComponent={
          <Text style={styles.emptyText}>
            {debouncedQuery ? 'No locations match your search.' : 'No locations available.'}
          </Text>
        }
      />
    </View>
  );
}

/* ─── Sub-components ─── */

interface BuildingAccordionProps {
  building: import('../../hooks/useLocationSearch').SearchBuilding;
  onNodeSelect: (node: NavNode) => void;
}

function BuildingAccordion({ building, onNodeSelect }: BuildingAccordionProps) {
  const [expanded, setExpanded] = useState(false);

  return (
    <View style={styles.buildingSection}>
      <Pressable style={styles.buildingHeader} onPress={() => setExpanded(e => !e)}>
        <View style={styles.buildingInfo}>
          <Text style={styles.buildingName}>{building.buildingName}</Text>
          <Text style={styles.buildingMeta}>
            {building.floors.length} {building.floors.length === 1 ? 'floor' : 'floors'} ·{' '}
            {building.floors.reduce((sum, f) => sum + f.nodes.length, 0)} locations
          </Text>
        </View>
        <Text style={styles.chevron}>{expanded ? '▼' : '▶'}</Text>
      </Pressable>

      {expanded && (
        <View style={styles.floorsContainer}>
          {building.floors.map(floor => (
            <FloorSection key={floor.floorId} floor={floor} onNodeSelect={onNodeSelect} />
          ))}
        </View>
      )}
    </View>
  );
}

interface FloorSectionProps {
  floor: import('../../hooks/useLocationSearch').SearchFloor;
  onNodeSelect: (node: NavNode) => void;
}

function FloorSection({ floor, onNodeSelect }: FloorSectionProps) {
  return (
    <View style={styles.floorSection}>
      <Text style={styles.floorHeader}>Floor {floor.floorNumber}</Text>
      {floor.nodes.map(sn => (
        <NodeRow key={sn.node.id} searchNode={sn} onPress={() => onNodeSelect(sn.node)} />
      ))}
    </View>
  );
}

interface NodeRowProps {
  searchNode: import('../../hooks/useLocationSearch').SearchNode;
  onPress: () => void;
}

function NodeRow({ searchNode, onPress }: NodeRowProps) {
  const { node, buildingName, floorNumber } = searchNode;
  const badge = TYPE_BADGE[node.type] ?? '📍';
  const isAccessible = node.type === 'elevator' || node.type === 'ramp';

  return (
    <Pressable style={styles.nodeRow} onPress={onPress}>
      <Text style={styles.nodeBadge}>{badge}</Text>
      <View style={styles.nodeInfo}>
        <Text style={styles.nodeLabel}>{node.label}</Text>
        <Text style={styles.nodeSubtext}>
          {buildingName} · Floor {floorNumber}
          {node.roomNumber ? ` · Room ${node.roomNumber}` : ''}
        </Text>
      </View>
      {isAccessible && <Text style={styles.accessibleIcon}>{ACCESSIBLE_ICON}</Text>}
    </Pressable>
  );
}

/* ─── Styles (dark theme, campusnav palette) ─── */

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#020617' },
  header: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: 16, paddingTop: 12, paddingBottom: 8 },
  headerLabel: { color: '#f8fafc', fontSize: 18, fontWeight: '700' },
  resultCount: { color: '#64748b', fontSize: 13 },
  searchInput: {
    marginHorizontal: 16,
    marginBottom: 8,
    backgroundColor: '#0f172a',
    borderColor: '#1e293b',
    borderWidth: 1,
    borderRadius: 10,
    paddingHorizontal: 14,
    paddingVertical: 10,
    color: '#f8fafc',
    fontSize: 15,
  },
  fieldToggle: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingBottom: 10, gap: 8 },
  fieldText: { color: '#94a3b8', fontSize: 13 },
  fieldChip: { backgroundColor: '#0f172a', borderColor: '#334155', borderWidth: 1, borderRadius: 16, paddingHorizontal: 10, paddingVertical: 4 },
  fieldChipActive: { backgroundColor: '#1e3a5f', borderColor: '#38bdf8' },
  fieldChipText: { color: '#94a3b8', fontSize: 12 },
  fieldChipTextActive: { color: '#38bdf8', fontWeight: '600' },
  swapButton: { marginLeft: 'auto', backgroundColor: '#0f172a', borderColor: '#334155', borderWidth: 1, borderRadius: 16, paddingHorizontal: 10, paddingVertical: 4 },
  swapButtonText: { color: '#94a3b8', fontSize: 12 },
  list: { flex: 1 },
  emptyText: { color: '#475569', fontSize: 14, textAlign: 'center', marginTop: 40 },
  buildingSection: { borderBottomColor: '#1e293b', borderBottomWidth: 1 },
  buildingHeader: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingVertical: 12 },
  buildingInfo: { flex: 1 },
  buildingName: { color: '#f8fafc', fontSize: 16, fontWeight: '600' },
  buildingMeta: { color: '#64748b', fontSize: 12, marginTop: 2 },
  chevron: { color: '#38bdf8', fontSize: 12 },
  floorsContainer: { backgroundColor: '#0a0f1e', paddingLeft: 16 },
  floorSection: { paddingVertical: 6 },
  floorHeader: { color: '#475569', fontSize: 11, fontWeight: '600', letterSpacing: 1, paddingHorizontal: 16, paddingVertical: 4, textTransform: 'uppercase' },
  nodeRow: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingVertical: 10, gap: 10 },
  nodeBadge: { fontSize: 16, width: 24, textAlign: 'center' },
  nodeInfo: { flex: 1 },
  nodeLabel: { color: '#e2e8f0', fontSize: 14, fontWeight: '500' },
  nodeSubtext: { color: '#64748b', fontSize: 11, marginTop: 2 },
  accessibleIcon: { fontSize: 14 },
});

/**
 * LiveGuidanceOverlay — real-time guidance overlay driven by GuidanceState.
 *
 * Conditionally renders one of five UI variants based on `guidanceState.phase`:
 * - `idle`          → nothing
 * - `low-confidence` → orange banner prompting position confirmation
 * - `guiding`       → step card with instruction, icon, distance, progress
 * - `rerouting`     → blue banner with spinner
 * - `arrived`       → green celebration card
 */

import { ActivityIndicator, Pressable, StyleSheet, Text, View } from 'react-native';
import { useRef, useState } from 'react';

import { getActiveStep, GuidanceState } from '../../routing/guidanceState';
import { DirectionStep, NormalizedFloorRecord } from '../../domain/navGraph';
import { ConfidenceIndicator, ConfidenceLevel } from './ConfidenceIndicator';

// ─── Step icon helpers (mirrors RoutePreview) ────────────────────────────────

const STEP_ICONS: Record<string, string> = {
  'straight': '↑',
  'turn-left': '←',
  'turn-right': '→',
  'sharp-left': '↙',
  'sharp-right': '↘',
  'arrive': '🏁',
  'accessible': '♿',
  'stairs-up': '⬆',
  'stairs-down': '⬇',
  'elevator': '🛗',
  'ramp': '♿',
};

function stepIcon(step: DirectionStep): string {
  return STEP_ICONS[step.icon] ?? '→';
}

// ─── Distance formatting ─────────────────────────────────────────────────────

/**
 * Format a normalized distance as a human-readable string.
 * Normalized coordinate space → approximate real distance (50 m per unit).
 */
function formatDistance(norm: number): string {
  const meters = Math.round(norm * 50);
  if (meters < 1) return '<1m';
  if (meters >= 1000) return `${(meters / 1000).toFixed(1)}km`;
  return `${meters}m`;
}

/**
 * Sum of distances for all steps from currentStepIndex onward.
 */
function remainingDistance(state: GuidanceState): number {
  const { route, currentStepIndex } = state;
  if (route.phase !== 'ready' || !route.directions) return 0;
  return route.directions.steps
    .slice(currentStepIndex)
    .reduce((sum, s) => sum + s.distanceM, 0);
}

// ─── Props ───────────────────────────────────────────────────────────────────

export interface LiveGuidanceOverlayProps {
  guidanceState: GuidanceState;
  onConfirmPosition: () => void;
  onStopGuidance: () => void;
  /** Floor ID of the current snapped position. */
  floorId?: number | null;
  /** Floor lookup map for display labels. */
  floorMap?: Map<number, NormalizedFloorRecord>;
  /** When true, applies accessible mode styling to elevator/ramp steps. */
  accessibleMode?: boolean;
}

// ─── Sub-components ───────────────────────────────────────────────────────────

/** Low-confidence banner: orange/yellow background, confirm button. */
function LowConfidenceBanner({
  onConfirmPosition,
  floorId,
  floorMap,
}: {
  onConfirmPosition: () => void;
  floorId?: number | null;
  floorMap?: Map<number, NormalizedFloorRecord>;
}) {
  const floorLabel = floorId && floorMap ? floorMap.get(floorId)?.floor.floorNumber ?? floorId : null;

  return (
    <View style={styles.lowConfidenceBanner} testID="low-confidence-banner">
      <View style={styles.bannerRow}>
        <ConfidenceIndicator confidence="low" />
        <Text style={styles.lowConfidenceText}>
          Can't confirm your location.{'\n'}
          Tap the map to confirm where you are, or move to an open area.
          {floorLabel != null ? `\nYou are on Floor ${floorLabel}.` : ''}
        </Text>
      </View>
      <Pressable style={styles.confirmButton} onPress={onConfirmPosition} testID="confirm-position-btn">
        <Text style={styles.confirmButtonText}>Confirm location</Text>
      </Pressable>
    </View>
  );
}

/** Rerouting banner: blue background with spinner. */
function ReroutingBanner() {
  return (
    <View style={styles.reroutingBanner} testID="rerouting-banner">
      <ActivityIndicator color="#38bdf8" size="small" />
      <Text style={styles.reroutingText}>Recalculating your route...</Text>
    </View>
  );
}

/** Main guiding card: step instruction, icon, distance, progress. */
function GuidingCard({
  state,
  onStopGuidance,
  floorId,
  floorMap,
  accessibleMode,
}: {
  state: GuidanceState;
  onStopGuidance: () => void;
  floorId?: number | null;
  floorMap?: Map<number, NormalizedFloorRecord>;
  accessibleMode?: boolean;
}) {
  const activeStep = getActiveStep(state);
  const { route, currentStepIndex, positionConfidence } = state;

  const totalSteps = route.phase === 'ready' && route.directions
    ? route.directions.steps.length
    : 0;
  const progressLabel = `Step ${currentStepIndex + 1} of ${totalSteps}`;
  const remaining = remainingDistance(state);

  const isAccessibleStep = activeStep?.icon === 'elevator' || activeStep?.icon === 'ramp';
  const highlightAccessible = accessibleMode && isAccessibleStep;

  let instruction = activeStep?.instruction ?? 'Navigating...';
  if (highlightAccessible) {
    instruction = `${instruction} (accessible)`;
  }

  const icon = activeStep ? stepIcon(activeStep) : '→';

  return (
    <View style={styles.guidingCard} testID="guiding-card">
      {/* Top row: step icon + instruction */}
      <View style={styles.stepRow}>
        <View style={[styles.stepIconContainer, highlightAccessible && styles.stepIconContainerAccessible]}>
          <Text style={[styles.stepIcon, highlightAccessible && styles.stepIconAccessible]}>{icon}</Text>
        </View>
        <Text style={styles.instructionText} numberOfLines={2}>
          {instruction}
        </Text>
        <ConfidenceIndicator confidence={positionConfidence} />
      </View>

      {/* Floor badge row */}
      <FloorBadge floorId={floorId} floorMap={floorMap} />

      {/* Bottom row: distance + progress + end button */}
      <View style={styles.bottomRow}>
        <Text style={styles.distanceText}>{formatDistance(remaining)} remaining</Text>
        <Text style={styles.progressText}>{progressLabel}</Text>
        <Pressable onPress={onStopGuidance} testID="stop-guidance-btn">
          <Text style={styles.endButton}>End guidance</Text>
        </Pressable>
      </View>
    </View>
  );
}

/** Arrived celebration card. */
function ArrivedCard({
  state,
  onStopGuidance,
}: {
  state: GuidanceState;
  onStopGuidance: () => void;
}) {
  const destLabel =
    state.route.phase === 'ready' && state.route.destination
      ? state.route.destination.label
      : 'Destination';

  return (
    <View style={styles.arrivedCard} testID="arrived-card">
      <Text style={styles.checkmark}>✅</Text>
      <Text style={styles.arrivedTitle}>You've arrived!</Text>
      <Text style={styles.arrivedDest}>{destLabel}</Text>
      <Pressable style={styles.doneButton} onPress={onStopGuidance} testID="done-btn">
        <Text style={styles.doneButtonText}>Done</Text>
      </Pressable>
    </View>
  );
}

/** Floor badge — shows current floor label next to step icon in the guiding card. */
function FloorBadge({
  floorId,
  floorMap,
}: {
  floorId?: number | null;
  floorMap?: Map<number, NormalizedFloorRecord>;
}) {
  if (!floorId || !floorMap) return null;
  const record = floorMap.get(floorId);
  if (!record) return null;
  return (
    <View style={styles.floorBadge} testID="floor-badge">
      <Text style={styles.floorBadgeText}>Floor {record.floor.floorNumber}</Text>
    </View>
  );
}

/** Floor transition banner — briefly shown for 2500 ms when floor changes. */
function FloorTransitionBanner({
  floorId,
  floorMap,
}: {
  floorId?: number | null;
  floorMap?: Map<number, NormalizedFloorRecord>;
}) {
  const prevFloorIdRef = useRef<number | null>(null);
  const [visible, setVisible] = useState(false);
  const [displayFloorId, setDisplayFloorId] = useState<number | null>(null);

  const safeFloorId: number | null = floorId ?? null;

  if (safeFloorId !== null && safeFloorId !== prevFloorIdRef.current && prevFloorIdRef.current !== null) {
    prevFloorIdRef.current = safeFloorId;
    const label = floorMap?.get(safeFloorId)?.floor.floorNumber ?? safeFloorId;
    setDisplayFloorId(safeFloorId);
    setVisible(true);
    setTimeout(() => setVisible(false), 2500);
  } else if (safeFloorId !== null) {
    prevFloorIdRef.current = safeFloorId;
  }

  if (!visible || displayFloorId === null) return null;

  const label = floorMap?.get(displayFloorId)?.floor.floorNumber ?? displayFloorId;

  return (
    <View style={styles.floorTransitionBanner} testID="floor-transition-banner">
      <Text style={styles.floorTransitionText}>Now on Floor {label}</Text>
    </View>
  );
}

// ─── Main component ──────────────────────────────────────────────────────────

export function LiveGuidanceOverlay({
  guidanceState,
  onConfirmPosition,
  onStopGuidance,
  floorId,
  floorMap,
  accessibleMode,
}: LiveGuidanceOverlayProps) {
  const { phase } = guidanceState;

  if (phase === 'idle') return null;

  if (phase === 'low-confidence') {
    return <LowConfidenceBanner onConfirmPosition={onConfirmPosition} floorId={floorId} floorMap={floorMap} />;
  }

  if (phase === 'rerouting') {
    return <ReroutingBanner />;
  }

  if (phase === 'arrived') {
    return <ArrivedCard state={guidanceState} onStopGuidance={onStopGuidance} />;
  }

  // phase === 'guiding'
  return (
    <>
      <FloorTransitionBanner floorId={floorId} floorMap={floorMap} />
      <GuidingCard
        state={guidanceState}
        onStopGuidance={onStopGuidance}
        floorId={floorId}
        floorMap={floorMap}
        accessibleMode={accessibleMode}
      />
    </>
  );
}

// ─── Styles ──────────────────────────────────────────────────────────────────

const styles = StyleSheet.create({
  // Low-confidence banner
  lowConfidenceBanner: {
    backgroundColor: '#7c2d12',
    borderColor: '#f97316',
    borderWidth: 1,
    borderRadius: 12,
    padding: 14,
    margin: 12,
    gap: 10,
  },
  bannerRow: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    gap: 10,
  },
  lowConfidenceText: {
    flex: 1,
    color: '#fed7aa',
    fontSize: 13,
    lineHeight: 18,
  },
  confirmButton: {
    backgroundColor: '#f97316',
    borderRadius: 8,
    paddingVertical: 8,
    paddingHorizontal: 16,
    alignItems: 'center',
  },
  confirmButtonText: {
    color: '#fff',
    fontSize: 14,
    fontWeight: '700',
  },

  // Rerouting banner
  reroutingBanner: {
    backgroundColor: '#0c2d4a',
    borderColor: '#38bdf8',
    borderWidth: 1,
    borderRadius: 12,
    padding: 16,
    margin: 12,
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
  },
  reroutingText: {
    color: '#7dd3fc',
    fontSize: 14,
    fontWeight: '600',
  },

  // Guiding card
  guidingCard: {
    backgroundColor: '#0f172a',
    borderColor: '#1e3a5f',
    borderWidth: 1,
    borderRadius: 14,
    padding: 14,
    margin: 12,
    gap: 10,
  },
  stepRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
  },
  stepIconContainer: {
    width: 36,
    height: 36,
    borderRadius: 8,
    backgroundColor: '#1e3a5f',
    alignItems: 'center',
    justifyContent: 'center',
  },
  stepIconContainerAccessible: {
    backgroundColor: '#facc15',
  },
  stepIcon: {
    fontSize: 18,
    color: '#38bdf8',
    fontWeight: '700',
  },
  stepIconAccessible: {
    color: '#1e3a5f',
  },
  instructionText: {
    flex: 1,
    color: '#f1f5f9',
    fontSize: 16,
    fontWeight: '600',
    lineHeight: 22,
  },
  bottomRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  distanceText: {
    color: '#38bdf8',
    fontSize: 12,
    fontWeight: '600',
  },
  progressText: {
    color: '#475569',
    fontSize: 12,
    flex: 1,
  },
  endButton: {
    color: '#64748b',
    fontSize: 12,
    textDecorationLine: 'underline',
  },

  // Arrived card
  arrivedCard: {
    backgroundColor: '#052e16',
    borderColor: '#22c55e',
    borderWidth: 1,
    borderRadius: 14,
    padding: 20,
    margin: 12,
    alignItems: 'center',
    gap: 8,
  },
  checkmark: {
    fontSize: 32,
  },
  arrivedTitle: {
    color: '#4ade80',
    fontSize: 20,
    fontWeight: '700',
  },
